                       (request_id,team,owner,str(home),task_id,json.dumps(source),task,kind,label,origin,identifier,now,now+({'code':300,'payment':900}.get(kind,1800)),handle,checkout_json,grant_id,approver,gateway_event_id))
            return dict(db.execute('SELECT * FROM requests WHERE id=?', (request_id,)).fetchone())

    def get(self, request_id, token, *, identity=None, waiting=True):
